package com.example.starter.domain;

/**
 * 信号字节序。
 */
public enum ByteOrder {
    /** 大端（DBC Motorola，锯齿形位编号）。 */
    BIG_ENDIAN,
    /** 小端（DBC Intel）。 */
    LITTLE_ENDIAN
}

package com.example.starter.domain;

/**
 * 信号在多路复用报文中的角色。
 */
public enum MultiplexRole {
    /** 普通信号：每帧都参与解码。 */
    NONE,
    /** 多路选择器：其原始值决定本帧激活哪个被选择信号分支。 */
    MULTIPLEXOR,
    /** 被选择信号：仅当选择器原始值等于 multiplexValue 时参与解码。 */
    MULTIPLEXED
}

package com.example.starter.domain;

/**
 * 帧解析可区分的拒绝原因。
 */
public enum RejectReason {
    /** 负载长度与报文定义 DLC 不一致。 */
    BAD_LENGTH,
    /** 当前 DBC 版本中不存在该 CAN ID 的报文定义。 */
    UNKNOWN_ID,
    /** 报文存在被选择信号，但选择器原始值未匹配任何分支。 */
    MUX_NOT_MATCH,
    /** 旧时戳或较低序号帧，不得覆盖最新状态。 */
    STALE_FRAME,
    /** 相同时戳与相同序号的帧重放。 */
    DUPLICATE_FRAME
}

