        tableA.put(0L, "Off");
        tableA.put(1L, "On");
        java.util.Map<Long, String> tableB = new java.util.LinkedHashMap<>();
        tableB.put(1L, "On");
        tableB.put(0L, "Off");

        var request1 = TestDbcFactory.version("v1", "req-1")
                .message(0x100, "SwitchMsg", 1)
