        System.out.println("AUDIT ROWS: " + jdbcTemplate.queryForList(
                "SELECT frame_seq, accepted, reject_reason FROM frame_audit ORDER BY id"));
        System.out.println("STATE ROWS: " + jdbcTemplate.queryForList(
                "SELECT signal_name, frame_seq, raw_value FROM signal_state"));
